// Function node to parse agent response
try {
    // Get the raw output and log it
    const rawOutput = $input.item.json.output;
    console.log('Raw output:', rawOutput);

    // Remove markdown code block syntax and extract JSON
    const jsonString = rawOutput
        .replace(/```json\n?/, '')  // Remove opening ```json
        .replace(/\n?```$/, '')     // Remove closing ```
        .trim();                    // Remove any extra whitespace

    // Parse the cleaned JSON string
    const parsedResponse = JSON.parse(jsonString);

    // Create the response object
    const response = {
        message: parsedResponse.message || "Greetings, seeker! Let's begin your journey!",
        resumeHtml: parsedResponse.resumeHtml || "<div class='resume-journey'><h3>Your Career Path Begins...</h3></div>",
        collectedInfo: parsedResponse.collectedInfo || {
            personalInfo: { collected: false, data: null },
            education: { collected: false, data: null },
            experience: { collected: false, data: null },
            skills: { collected: false, data: null }
        }
    };

    // Return a single object, not an array
    return response;

} catch (error) {
    console.log('Error details:', error.message);
    console.log('Raw input:', $input.item.json[0].output);

    // Return a properly formatted error response
    return {
        message: "Apologies, seeker! Even gurus face technical challenges sometimes. Let's try that again! 🙏",
        resumeHtml: "<div class='resume-journey'><h3>Ready to Begin Your Journey...</h3></div>",
        collectedInfo: {
            personalInfo: { collected: false, data: null },
            education: { collected: false, data: null },
            experience: { collected: false, data: null },
            skills: { collected: false, data: null }
        }
    };
}
